// Verify status code
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Parse response
const users = pm.response.json();

// Verify response is a non-empty array
pm.test("Response is a non-empty array", function () {
    pm.expect(users).to.be.an("array").that.is.not.empty;
});

// Verify user information
pm.test("Users contain id, name, and email", function () {
    users.forEach(function (user) {
        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("name");
        pm.expect(user).to.have.property("email");
    });
});

// Save the first user's ID for Q2
const userId = users[0].id;
pm.collectionVariables.set("userId", userId);

console.log("Saved User ID:", userId);

pm.collectionVariables.set("userData", JSON.stringify(users[0]));
pm.collectionVariables.set("originalPhone", users[0].phone);

const timestamp = Date.now();

const updatedName = "QA Tester " + timestamp;
const updatedEmail = "qa.tester." + timestamp + "@example.com";
const updatedCompany = "QA Company " + timestamp;

pm.collectionVariables.set("updatedName", updatedName);
pm.collectionVariables.set("updatedEmail", updatedEmail);
pm.collectionVariables.set("updatedCompany", updatedCompany);

const response = pm.response.json();

pm.test("PUT status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Returned ID matches saved user ID", function () {
    pm.expect(response.id).to.eql(
        Number(pm.collectionVariables.get("userId"))
    );
});

pm.test("Updated name matches", function () {
    pm.expect(response.name).to.eql(
        pm.collectionVariables.get("updatedName")
    );
});

pm.test("Phone number is not empty", function () {
    pm.expect(response.phone).to.be.a("string").and.not.empty;
});

pm.test("Email is updated", function () {
    pm.expect(response.email).to.eql(
        pm.collectionVariables.get("updatedEmail")
    );
});

pm.test("Company name is updated", function () {
    pm.expect(response.company.name).to.eql(
        pm.collectionVariables.get("updatedCompany")
    );
});
